SELECT FROM crm_webchat_conversation cv
LEFT JOIN sys_user u ON CAST(u.user_id AS VARCHAR) = cv.user_id LEFT JOIN sys_dept d ON u.dept_id = d.dept_id
cv.tenant_id = #{tenantId}
AND cv.user_id IS NULL AND cv.status <> 'blocked'
AND cv.user_id = CAST(#{currentUserId} AS VARCHAR) AND cv.status <> 'blocked'
AND cv.user_id IS NOT NULL AND cv.status <> 'blocked' ${params.dataScope}
AND cv.status = #{status}
AND (cv.visitor_id ILIKE '%' || #{keyword} || '%' OR cv.profile_name ILIKE '%' || #{keyword} || '%' OR cv.owner ILIKE '%' || #{keyword} || '%' OR cv.last_message_preview ILIKE '%' || #{keyword} || '%')
AND cv.id = #{conversationId}
ORDER BY cv.last_message_at DESC NULLS LAST

SELECT COUNT(1)
FROM crm_webchat_conversation cv

    LEFT JOIN sys_user u ON CAST(u.user_id AS VARCHAR) = cv.user_id
    LEFT JOIN sys_dept d ON u.dept_id = d.dept_id


    cv.tenant_id = #{tenantId}

        AND cv.user_id IS NOT NULL
        AND cv.status <> 'blocked'
        ${params.dataScope}


        AND cv.id = #{conversationId}

